#| 0, 1, ..., n - 1.
def py_iota(n) {
    a = zeros(n)
    for i to n {
        a[i] = i
    }
    return a
}

#| Every entry of a real array, row-major, as a vector (a copy).
def py_flat(a: Arr) {
    return take(a, py_iota(numel(a)))
}

#| np.arange(start, stop, step), as NumPy fills it: ceil((stop - start) / step) entries,
#| entry k = start + k * delta with delta = (start + step) - start.
def py_arange(start, stop_, step) {
    if step == 0 {
        stop("ZeroDivisionError: division by zero")
    }
    if not (abs((stop_ - start) / step) < 1.0 / 0.0) {
        stop("py2viv: np.arange of a length that is not finite (NumPy raises ValueError)")
    }
    n = max(ceil((stop_ - start) / step), 0)
    a = zeros(n)
    delta = (start + step) - start
    for k to n {
        a[k] = start + k * delta
    }
    return a
}

#| np.mean(a): NumPy's pairwise sum over numel(a).
def py_mean(a: Arr) {
    return py_npsum(a) / numel(a)
}

#| np.var(a): the pairwise sum of the squared deviations over n, as NumPy's _var computes it.
def py_var(a: Arr) {
    d = a - py_mean(a)
    return py_npsum(d * d) / numel(a)
}

#| np.std(a): divides by n, as NumPy does (lib/stats `std`).
def py_std(a: Arr) {
    return sqrt(py_var(a))
}

#| An int result, as Python's int: a -0.0 becomes 0 (an int has no sign on zero), and the run
#| stops at 2^53, past which a double no longer holds every integer (Python's int does).
def py_int(x) {
    if abs(x) >= 9007199254740992 {
        stop("py2viv: an integer reached 2^53; Python's int is exact there and a double is not")
    }
    return x + 0.0
}

#| a / b of two ints: ZeroDivisionError on a zero divisor.
def py_div_i(a, b) {
    if b == 0 {
        stop("ZeroDivisionError: division by zero")
    }
    return a / b
}

#| NumPy's pairwise sum of f[lo], ..., f[lo + n - 1] (numpy/core/src/umath/loops_utils.h):
#| below 8 terms left to right from 0; to 128, eight running sums combined as a tree, then
#| the rest; above, the two halves (the first a multiple of 8 long) summed apart.
def py_pw(f: Arr, lo, n) {
    if n < 8 {
        s = 0.0
        for i to n {
            s += f[lo + i]
        }
        return s
    }
    if n <= 128 {
        r = zeros(8)
        for j to 8 {
            r[j] = f[lo + j]
        }
        i = 8
        while i < n - n % 8 {
            for j to 8 {
                r[j] += f[lo + i + j]
            }
            i += 8
        }
        s = ((r[0] + r[1]) + (r[2] + r[3])) + ((r[4] + r[5]) + (r[6] + r[7]))
        while i < n {
            s += f[lo + i]
            i += 1
        }
        return s
    }
    n2 = floor(n / 2)
    n2 = n2 - n2 % 8
    return py_pw(f, lo, n2) + py_pw(f, lo + n2, n - n2)
}

#| NumPy's sum of f[lo], ..., f[lo + n - 1] along one axis: from 0.0, a pairwise sum of each
#| block of NumPy's buffer size (8192 entries), added in order.
def py_blk(f: Arr, lo, n) {
    bufsize = 8192
    s = 0.0
    b = 0
    while b < n {
        s = s + py_pw(f, lo + b, min(bufsize, n - b))
        b += bufsize
    }
    return s
}

#| np.sum(a), a.sum() of a float array: NumPy's sum over the entries in row-major order (py_blk).
def py_npsum(a: Arr) {
    f = py_flat(a)
    return py_blk(f, 0, len(f))
}

#| The sum of an integer array or list, exactly: every partial sum checked below 2^53.
def py_isum(a: Arr) {
    f = py_flat(a)
    s = 0
    for i to len(f) {
        s = py_int(s + f[i])
    }
    return s
}

#| An array size, as NumPy takes it: ValueError for a negative one (Viv would make an empty
#| array).
def py_size(n) {
    if n < 0 {
        stop("ValueError: negative dimensions are not allowed")
    }
    return n
}

#| The shape NumPy broadcasts two shapes da and db to (aligned at the last axis, a length 1
#| stretched); the run stops where NumPy raises ValueError.
def py_bdims(da: Arr, db: Arr) {
    n = len(da)
    if len(db) > n {
        n = len(db)
    }
    e = zeros(n)
    for i to n {
        x = 1
        y = 1
        if i >= n - len(da) {
            x = da[i - n + len(da)]
        }
        if i >= n - len(db) {
            y = db[i - n + len(db)]
        }
        if x == y or y == 1 {
            e[i] = x
        }
        else {
            if x == 1 {
                e[i] = y
            }
            else {
                stop("ValueError: operands could not be broadcast together with shapes")
            }
        }
    }
    return e
}

#| The flat indices, in row-major order of the shape e, of the entries of an array of shape d
#| that broadcasting to e reads (a length 1 of d is read again along that axis of e).
def py_bidx(d: Arr, e: Arr) {
    n = len(e)
    m = len(d)
    st = zeros(n)
    s = 1
    for k to m {
        j = m - 1 - k
        if d[j] != 1 {
            st[j + n - m] = s
        }
        s = s * d[j]
    }
    idx = zeros(1)
    for i to n {
        w = e[i]
        nxt = zeros(len(idx) * w)
        for p to len(idx) {
            for c to w {
                nxt[p * w + c] = idx[p] + c * st[i]
            }
        }
        idx = nxt
    }
    return idx
}

#| a broadcast to the shape e (a shape py_bdims gave for a and another array): a itself when
#| it has that shape, else a new array whose entries are copies of a's.
def py_bto(a: Arr, e: Arr) {
    d = shape(a)
    if len(d) == len(e) {
        if all(d == e) {
            return a
        }
    }
    return py_shaped(take(a, py_bidx(d, e)), e)
}

#| a + b of two real arrays, broadcast as NumPy broadcasts them.
def py_badd(a: Arr, b: Arr) {
    e = py_bdims(shape(a), shape(b))
    return py_bto(a, e) + py_bto(b, e)
}

#| The flat indices of the nonzero entries of m, in order (a NaN is nonzero, -0.0 is zero).
def py_nzflat(m: Arr) {
    f = py_flat(m)
    c = 0
    for i to len(f) {
        if f[i] != 0 {
            c += 1
        }
    }
    r = zeros(c)
    c = 0
    for i to len(f) {
        if f[i] != 0 {
            r[c] = i
            c += 1
        }
    }
    return r
}

#| The entries of f, row-major, as an array of shape e (a vector of 1 to 4 lengths).
def py_shaped(f: Arr, e: Arr) {
    if len(e) == 1 {
        return f
    }
    if len(e) == 2 {
        z = zeros(e[0], e[1])
    }
    else {
        if len(e) == 3 {
            z = zeros(e[0], e[1], e[2])
        }
        else {
            z = zeros(e[0], e[1], e[2], e[3])
        }
    }
    put(z, py_iota(numel(z)), f)
    return z
}

NPR_TWO32 = 4294967296.0
NPR_TWO53 = 9007199254740992.0
NPR_U32_MAX = 4294967295
NPR_TWO16 = 65536.0

#| `a * b mod 2^32` for words `a` and `b`: a = hi * 2^16 + lo, and each partial
#| product stays below 2^48.
def npr_mul32(a, b) {
    a_hi = floor(a / NPR_TWO16)
    a_lo = a - a_hi * NPR_TWO16
    return mod(a_lo * b + mod(a_hi * b, NPR_TWO16) * NPR_TWO16, NPR_TWO32)
}

#| `(a + b) mod 2^32`, and `(a - b) mod 2^32`, for words.
def npr_add32(a, b) {
    return mod(a + b, NPR_TWO32)
}

def npr_sub32(a, b) {
    return mod(a - b + NPR_TWO32, NPR_TWO32)
}

#| The smallest `2^k - 1` at or above `r` (NumPy's gen_mask), for 0 <= r < 2^63.
def npr_mask(r: Int) -> Int {
    m: Int = 0
    while m < r {
        m = m * 2 + 1
    }
    return m
}


# SPDX-License-Identifier: MIT OR Apache-2.0
# SPDX-FileCopyrightText: 2026 The Viv authors

NPR_N = 624
NPR_M = 397
# 0x9908b0df, 0x80000000, 0x7fffffff
NPR_MATRIX_A = 2567483615
NPR_UPPER_MASK = 2147483648
NPR_LOWER_MASK = 2147483647
# the tempering masks 0x9d2c5680 and 0xefc60000, and the shifts
NPR_TEMPER_B = 2636928640
NPR_TEMPER_C = 4022730752
NPR_TEMPER_U = 11
NPR_TEMPER_S = 7
NPR_TEMPER_T = 15
NPR_TEMPER_L = 18
# Knuth's multiplier (mt19937_seed, init_genrand), init_by_array's seed and multipliers
NPR_SEED_MULT = 1812433253
NPR_SEED_SHIFT = 30
NPR_INIT_SEED = 19650218
NPR_INIT_MULT1 = 1664525
NPR_INIT_MULT2 = 1566083941
# the double: a 27-bit and a 26-bit part
NPR_DOUBLE_SHIFT_A = 5
NPR_DOUBLE_SHIFT_B = 6
NPR_TWO26 = 67108864.0
# where the position and the seeded flag live in the state
NPR_MT_POS = NPR_N
NPR_MT_SEEDED = NPR_N + 1
NPR_MT_LEN = NPR_N + 2

#| A state nothing has seeded yet.
def npr_mt_new() {
    return zeros(NPR_MT_LEN)
}

#| mt19937_seed: np.random.seed(s) of an int s in [0, 2^32 - 1].
def npr_mt_seed(st: Arr, seed) {
    s = seed
    for pos to NPR_N {
        st[pos] = s
        s = npr_add32(npr_mul32(NPR_SEED_MULT, bxor(s, shr(s, NPR_SEED_SHIFT))), pos + 1)
    }
    st[NPR_MT_POS] = NPR_N
    st[NPR_MT_SEEDED] = 1
}

#| init_genrand: the start of init_by_array.
def npr_mt_init_genrand(st: Arr, s) {
    st[0] = s
    for i from 1 to NPR_N {
        st[i] = npr_add32(npr_mul32(NPR_SEED_MULT, bxor(st[i - 1], shr(st[i - 1], NPR_SEED_SHIFT))), i)
    }
    st[NPR_MT_POS] = NPR_N
}

#| mt19937_init_by_array: np.random.seed of an array of words.
def npr_mt_seed_array(st: Arr, key: Arr) {
    npr_mt_init_genrand(st, NPR_INIT_SEED)
    key_length = len(key)
    i = 1
    j = 0
    k = max(NPR_N, key_length)
    while k > 0 {
        prev = st[i - 1]
        mixed = npr_mul32(bxor(prev, shr(prev, NPR_SEED_SHIFT)), NPR_INIT_MULT1)
        st[i] = npr_add32(npr_add32(bxor(st[i], mixed), key[j]), j)
        i = i + 1
        j = j + 1
        if i >= NPR_N {
            st[0] = st[NPR_N - 1]
            i = 1
        }
        if j >= key_length {
            j = 0
        }
        k = k - 1
    }
    k = NPR_N - 1
    while k > 0 {
        prev = st[i - 1]
        mixed = npr_mul32(bxor(prev, shr(prev, NPR_SEED_SHIFT)), NPR_INIT_MULT2)
        st[i] = npr_sub32(bxor(st[i], mixed), i)
        i = i + 1
        if i >= NPR_N {
            st[0] = st[NPR_N - 1]
            i = 1
        }
        k = k - 1
    }
    st[0] = NPR_UPPER_MASK
    st[NPR_MT_POS] = NPR_N
    st[NPR_MT_SEEDED] = 1
}

#| mt19937_gen: all 624 words at once, in the reference's three runs. Word i
#| takes the upper bit of key[i] and the lower 31 of key[i + 1], shifted right
#| once, XORed with MATRIX_A when its lowest bit is set, and with key[i + M].
def npr_mt_gen(st: Arr) {
    for i to NPR_N - NPR_M {
        y = bor(band(st[i], NPR_UPPER_MASK), band(st[i + 1], NPR_LOWER_MASK))
        v = bxor(st[i + NPR_M], shr(y, 1))
        if band(y, 1) == 1 {
            v = bxor(v, NPR_MATRIX_A)
        }
        st[i] = v
    }
    for i from NPR_N - NPR_M to NPR_N - 1 {
        y = bor(band(st[i], NPR_UPPER_MASK), band(st[i + 1], NPR_LOWER_MASK))
        v = bxor(st[i + NPR_M - NPR_N], shr(y, 1))
        if band(y, 1) == 1 {
            v = bxor(v, NPR_MATRIX_A)
        }
        st[i] = v
    }
    y = bor(band(st[NPR_N - 1], NPR_UPPER_MASK), band(st[0], NPR_LOWER_MASK))
    v = bxor(st[NPR_M - 1], shr(y, 1))
    if band(y, 1) == 1 {
        v = bxor(v, NPR_MATRIX_A)
    }
    st[NPR_N - 1] = v
    st[NPR_MT_POS] = 0
}

#| mt19937_next: the next word, tempered.
def npr_mt_next32(st: Arr) {
    if st[NPR_MT_POS] == NPR_N {
        npr_mt_gen(st)
    }
    pos = st[NPR_MT_POS]
    y = st[pos]
    st[NPR_MT_POS] = pos + 1
    y = bxor(y, shr(y, NPR_TEMPER_U))
    y = bxor(y, band(shl(y, NPR_TEMPER_S), NPR_TEMPER_B))
    y = bxor(y, band(shl(y, NPR_TEMPER_T), NPR_TEMPER_C))
    return bxor(y, shr(y, NPR_TEMPER_L))
}

#| mt19937_next_double: a double in [0, 1) from two words.
def npr_mt_double(st: Arr) {
    a = shr(npr_mt_next32(st), NPR_DOUBLE_SHIFT_A)
    b = shr(npr_mt_next32(st), NPR_DOUBLE_SHIFT_B)
    return (a * NPR_TWO26 + b) / NPR_TWO53
}

#| mt19937_next64 ANDed with a mask: the first word drawn is the high one.
def npr_mt_masked64(st: Arr, mask: Int) -> Int {
    hi: Int = int(npr_mt_next32(st))
    lo: Int = int(npr_mt_next32(st))
    return band(bor(shl(hi, 32), lo), mask)
}

# SPDX-License-Identifier: MIT OR Apache-2.0
# SPDX-FileCopyrightText: 2026 The Viv authors

#| random_uniform: low + rng * a double in [0, 1).
def npr_lg_uniform(st: Arr, low, rng) {
    return low + rng * npr_mt_double(st)
}

#| A masked 32-bit draw at or below rng (rng < 2^32 - 1, mask = gen_mask(rng)).
def npr_lg_masked32(st: Arr, rng, mask: Int) {
    v = band(int(npr_mt_next32(st)), mask)
    while v > rng {
        v = band(int(npr_mt_next32(st)), mask)
    }
    return float(v)
}

#| A masked 64-bit draw at or below rng (2^32 <= rng < 2^53).
def npr_lg_masked64(st: Arr, rng, mask: Int) {
    v = npr_mt_masked64(st, mask)
    while v > rng {
        v = npr_mt_masked64(st, mask)
    }
    return float(v)
}

#| random_bounded_uint64 with use_masked: an int in [0, rng], 0 <= rng < 2^53.
def npr_lg_bounded(st: Arr, rng) {
    if rng == 0 {
        return 0
    }
    if rng == NPR_U32_MAX {
        return npr_mt_next32(st)
    }
    if rng < NPR_U32_MAX {
        return npr_lg_masked32(st, rng, npr_mask(int(rng)))
    }
    return npr_lg_masked64(st, rng, npr_mask(int(rng)))
}

#| random_interval: shuffle's draw of an int in [0, mx].
def npr_lg_interval(st: Arr, mx) {
    if mx == 0 {
        return 0
    }
    if mx <= NPR_U32_MAX {
        return npr_lg_masked32(st, mx, npr_mask(int(mx)))
    }
    return npr_lg_masked64(st, mx, npr_mask(int(mx)))
}

#| RandomState.shuffle of a vector, in place.
def npr_lg_shuffle(st: Arr, a: Arr) {
    n = len(a)
    for k to n - 1 {
        i = n - 1 - k
        j = npr_lg_interval(st, i)
        t = a[i]
        a[i] = a[j]
        a[j] = t
    }
}

#| RandomState.shuffle of a matrix: its rows, in place.
def npr_lg_shuffle_rows(st: Arr, A: Arr) {
    n = shape(A)[0]
    m = shape(A)[1]
    for k to n - 1 {
        i = n - 1 - k
        j = npr_lg_interval(st, i)
        if i != j {
            for c to m {
                t = A[i, c]
                A[i, c] = A[j, c]
                A[j, c] = t
            }
        }
    }
}

#| kahan_sum (numpy/random/_common.pyx): the sum choice checks p with.
def npr_kahan_sum(p: Arr) {
    n = len(p)
    if n == 0 {
        return 0.0
    }
    s = p[0]
    c = 0.0
    for i from 1 to n {
        y = p[i] - c
        t = s + y
        c = (t - s) - y
        s = t
    }
    return s
}

#| choice's cdf: p.cumsum() (in order), then each entry divided by the last.
def npr_lg_cdf(p: Arr) {
    cdf = cumsum(p)
    return cdf / cdf[len(p) - 1]
}

#| searchsorted(u, side='right') in a non-decreasing cdf: how many entries are <= u.
def npr_lg_search(cdf: Arr, u) {
    lo = 0
    hi = len(cdf)
    while lo < hi {
        mid = floor((lo + hi) / 2)
        if cdf[mid] <= u {
            lo = mid + 1
        }
        else {
            hi = mid
        }
    }
    return lo
}

# SPDX-License-Identifier: MIT OR Apache-2.0
# SPDX-FileCopyrightText: 2026 The Viv authors

NPR_SS_POOL_SIZE = 4
NPR_SS_XSHIFT = 16
# 0x43b0d7e5, 0x931e8875, 0x8b51f9dd, 0x58f38ded, 0xca01f9dd, 0x4973f715
NPR_SS_INIT_A = 1135663077
NPR_SS_MULT_A = 2468251765
NPR_SS_INIT_B = 2337405405
NPR_SS_MULT_B = 1492356589
NPR_SS_MIX_MULT_L = 3389127133
NPR_SS_MIX_MULT_R = 1232336661

#| The 32-bit words of n (0 <= n < 2^53), lowest first.
def npr_ss_words(n) {
    if n < NPR_TWO32 {
        return [n]
    }
    return [mod(n, NPR_TWO32), floor(n / NPR_TWO32)]
}

#| hashmix: value ^ hash_const, times the next hash_const, xor-shifted. The hash
#| constant lives in hc[0] and moves on with each call.
def npr_ss_hashmix(value, hc: Arr) {
    v = bxor(value, hc[0])
    hc[0] = npr_mul32(hc[0], NPR_SS_MULT_A)
    v = npr_mul32(v, hc[0])
    return bxor(v, shr(v, NPR_SS_XSHIFT))
}

#| mix: MIX_MULT_L * x - MIX_MULT_R * y, xor-shifted.
def npr_ss_mix(x, y) {
    r = npr_sub32(npr_mul32(NPR_SS_MIX_MULT_L, x), npr_mul32(NPR_SS_MIX_MULT_R, y))
    return bxor(r, shr(r, NPR_SS_XSHIFT))
}

#| mix_entropy: the pool of four words from the entropy words.
def npr_ss_pool(entropy: Arr) {
    pool = zeros(NPR_SS_POOL_SIZE)
    hc = [NPR_SS_INIT_A]
    n = len(entropy)
    for i to NPR_SS_POOL_SIZE {
        if i < n {
            pool[i] = npr_ss_hashmix(entropy[i], hc)
        }
        else {
            pool[i] = npr_ss_hashmix(0, hc)
        }
    }
    for i_src to NPR_SS_POOL_SIZE {
        for i_dst to NPR_SS_POOL_SIZE {
            if i_src != i_dst {
                pool[i_dst] = npr_ss_mix(pool[i_dst], npr_ss_hashmix(pool[i_src], hc))
            }
        }
    }
    for i_src from NPR_SS_POOL_SIZE to max(n, NPR_SS_POOL_SIZE) {
        for i_dst to NPR_SS_POOL_SIZE {
            pool[i_dst] = npr_ss_mix(pool[i_dst], npr_ss_hashmix(entropy[i_src], hc))
        }
    }
    return pool
}

#| generate_state: n_words 32-bit words from the pool, cycling through it.
def npr_ss_generate(pool: Arr, n_words) {
    out = zeros(n_words)
    hc = NPR_SS_INIT_B
    for i to n_words {
        v = bxor(pool[mod(i, NPR_SS_POOL_SIZE)], hc)
        hc = npr_mul32(hc, NPR_SS_MULT_B)
        v = npr_mul32(v, hc)
        out[i] = bxor(v, shr(v, NPR_SS_XSHIFT))
    }
    return out
}

# SPDX-License-Identifier: MIT OR Apache-2.0
# SPDX-FileCopyrightText: 2026 The Viv authors

# PCG_DEFAULT_MULTIPLIER_128 = 0x2360ed051fc65da44385df649fccf645, its halves
NPR_PCG_MULT_HI: Int = 2549297995355413924
NPR_PCG_MULT_LO: Int = 4865540595714422341
# the output rotation is the state's top 6 bits
NPR_PCG_ROT_SHIFT: Int = 58
NPR_BITS64: Int = 64
NPR_HALF64: Int = 32
NPR_LOW32: Int = 4294967295
# uint64_to_double: the top 53 bits of the output over 2^53
NPR_PCG_DOUBLE_SHIFT: Int = 11
NPR_PCG_SEED_WORDS = 8
# the state array: the state, the increment, the kept half, the last output, the seeded flag
NPR_PCG_LO = 0
NPR_PCG_HI = 1
NPR_PCG_INC = 2
NPR_PCG_HAS32 = 4
NPR_PCG_KEPT32 = 5
NPR_PCG_OUT = 6
NPR_PCG_SEEDED = 7
NPR_PCG_LEN = 8

#| A generator nothing has seeded.
def npr_pcg_new() -> [Int] {
    return int_zeros(NPR_PCG_LEN)
}

#| state = state * MULT + inc (mod 2^128), in 64-bit halves: the low half of
#| lo * MULT_LO, then its high half plus the cross products, then the
#| increment with the carry out of the low half.
def npr_pcg_step(st: [Int]) {
    lo = st[NPR_PCG_LO]
    hi = st[NPR_PCG_HI]
    p_lo = wrap_mul(lo, NPR_PCG_MULT_LO)
    p_hi = wrap_add(umulhi(lo, NPR_PCG_MULT_LO), wrap_add(wrap_mul(hi, NPR_PCG_MULT_LO), wrap_mul(lo, NPR_PCG_MULT_HI)))
    n_lo = wrap_add(p_lo, st[NPR_PCG_INC])
    carry: Int = 0
    if ult(n_lo, p_lo) {
        carry = 1
    }
    st[NPR_PCG_HI] = wrap_add(wrap_add(p_hi, st[NPR_PCG_INC + 1]), carry)
    st[NPR_PCG_LO] = n_lo
}

#| pcg64_next64: one step, then the XSL-RR output: (hi ^ lo) rotated right by
#| the state's top 6 bits (a shift by 64 is 0, as the rotation by 0 needs).
def npr_pcg_next64(st: [Int]) -> Int {
    npr_pcg_step(st)
    x = bxor(st[NPR_PCG_HI], st[NPR_PCG_LO])
    r = shr(st[NPR_PCG_HI], NPR_PCG_ROT_SHIFT)
    out = bor(shr(x, r), shl(x, NPR_BITS64 - r))
    st[NPR_PCG_OUT] = out
    return out
}

#| pcg64_next32: the low half of a fresh output; the high half is kept for the next call.
def npr_pcg_next32(st: [Int]) -> Int {
    if st[NPR_PCG_HAS32] == 1 {
        st[NPR_PCG_HAS32] = 0
        return st[NPR_PCG_KEPT32]
    }
    out = npr_pcg_next64(st)
    st[NPR_PCG_HAS32] = 1
    st[NPR_PCG_KEPT32] = shr(out, NPR_HALF64)
    return band(out, NPR_LOW32)
}

#| uint64_to_double(pcg64_next64): the output's top 53 bits over 2^53.
def npr_pcg_double(st: [Int]) {
    return float(shr(npr_pcg_next64(st), NPR_PCG_DOUBLE_SHIFT)) / NPR_TWO53
}

#| A 64-bit Int from two 32-bit words held in numbers: lo + 2^32 hi.
#@ 199eb438
def npr_word64(lo, hi) -> Int {
    l: Int = int(lo)
    h: Int = int(hi)
    return bor(l, shl(h, NPR_HALF64))
}

#| PCG64.__init__: seed from generate_state(4, np.uint64), given as its eight
#| 32-bit words w (the uint64 k is w[2k] + 2^32 w[2k + 1]): the state is
#| u64[0] * 2^64 + u64[1] and the sequence u64[2] * 2^64 + u64[3]. Then
#| pcg_setseq_128_srandom_r: inc = (seq << 1) | 1, a step, state += init, a step.
def npr_pcg_seed(st: [Int], w: Arr) {
    for i to NPR_PCG_LEN {
        st[i] = 0
    }
    seq_lo = npr_word64(w[6], w[7])
    seq_hi = npr_word64(w[4], w[5])
    st[NPR_PCG_INC] = bor(shl(seq_lo, 1), 1)
    st[NPR_PCG_INC + 1] = bor(shl(seq_hi, 1), shr(seq_lo, NPR_BITS64 - 1))
    npr_pcg_step(st)
    init_lo = npr_word64(w[2], w[3])
    init_hi = npr_word64(w[0], w[1])
    s_lo = wrap_add(st[NPR_PCG_LO], init_lo)
    carry: Int = 0
    if ult(s_lo, init_lo) {
        carry = 1
    }
    st[NPR_PCG_HI] = wrap_add(wrap_add(st[NPR_PCG_HI], init_hi), carry)
    st[NPR_PCG_LO] = s_lo
    npr_pcg_step(st)
    st[NPR_PCG_SEEDED] = 1
}

#| default_rng(seed) for the entropy words of the seed (SeedSequence(seed)).
def npr_pcg_from_entropy(entropy: Arr) -> [Int] {
    st = npr_pcg_new()
    npr_pcg_seed(st, npr_ss_generate(npr_ss_pool(entropy), NPR_PCG_SEED_WORDS))
    return st
}

