#| The sign bit of x (a -0.0 has it), false for NaN: NumPy's check of a non-negative parameter.
def py_npr_signbit(x) {
    return x < 0.0 or x == 0.0 and 1.0 / x < 0.0
}

#| np.random.default_rng(seed) of an int: SeedSequence(seed), then PCG64.
def py_npg_new(seed) {
    if seed < 0 {
        stop("ValueError: expected non-negative integer")
    }
    return npr_pcg_from_entropy(npr_ss_words(seed))
}

#| default_rng of an array of ints: each entry's words in turn (_coerce_to_uint32_array).
def py_npg_new_arr(seeds: Arr) {
    words = []
    for i to len(seeds) {
        if seeds[i] < 0 {
            stop("ValueError: expected non-negative integer")
        }
        w = npr_ss_words(seeds[i])
        for k to len(w) {
            words = append(words, w[k])
        }
    }
    return npr_pcg_from_entropy(words)
}

#| Generator.random(): one double; _v and _m fill a vector or matrix row by row.
def py_npg_random_v(st: [Int], n) {
    a = zeros(py_size(n))
    for i to n {
        a[i] = npr_pcg_double(st)
    }
    return a
}

def py_npg_random_m(st: [Int], rows, cols) {
    A = zeros(py_size(rows), py_size(cols))
    for i to rows {
        for j to cols {
            A[i, j] = npr_pcg_double(st)
        }
    }
    return A
}

#| Generator.standard_normal() and normal(loc, scale) = loc + scale * z. The ziggurat returns
#| NaN where NumPy's value depends on the platform's libm (the tail's log1p, a near-tie of the
#| wedge test's exp); the run stops there. scale must not carry a sign bit (NumPy's "scale <
#| 0", checked before the size).
def py_npg_z(st: [Int]) {
    v = npr_gn_normal(st)
    if v != v {
        stop("py2viv: a normal draw reached the ziggurat's tail (or a near-tie in its wedge test), where NumPy's value depends on the platform's log1p (or exp), which Viv's libm does not reproduce bit for bit")
    }
    return v
}

def py_npg_scale(scale) {
    if py_npr_signbit(scale) {
        stop("ValueError: scale < 0")
    }
    return scale
}

def py_npg_normal(st: [Int], loc, scale) {
    s = py_npg_scale(scale)
    return loc + s * py_npg_z(st)
}

def py_npg_normal_v(st: [Int], loc, scale, n) {
    s = py_npg_scale(scale)
    a = zeros(py_size(n))
    for i to n {
        a[i] = loc + s * py_npg_z(st)
    }
    return a
}

def py_npg_normal_m(st: [Int], loc, scale, rows, cols) {
    s = py_npg_scale(scale)
    A = zeros(py_size(rows), py_size(cols))
    for i to rows {
        for j to cols {
            A[i, j] = loc + s * py_npg_z(st)
        }
    }
    return A
}

#| Generator.integers(low, high, endpoint): low + a Lemire draw in [0, high - low] (high - 1
#| without the endpoint). An empty size gives an empty array before the bounds are checked.
def py_npg_irange(low, high, closed) {
    hi = high
    if closed == 0 {
        hi = high - 1
    }
    if low > hi {
        if closed == 1 {
            if low == 0 {
                stop("ValueError: high < 0")
            }
            stop("ValueError: low > high")
        }
        if low == 0 {
            stop("ValueError: high <= 0")
        }
        stop("ValueError: low >= high")
    }
    r = hi - low
    if r >= NPR_TWO53 {
        stop("py2viv: a random int range of 2^53 or more; a double holds the ints exactly only below it")
    }
    return r
}

def py_npg_integers(st: [Int], low, high, closed) {
    r = py_npg_irange(low, high, closed)
    return low + npr_gn_bounded(st, r)
}

def py_npg_integers_v(st: [Int], low, high, n, closed) {
    if n == 0 {
        return zeros(0)
    }
    r = py_npg_irange(low, high, closed)
    a = zeros(py_size(n))
    for i to n {
        a[i] = low + npr_gn_bounded(st, r)
    }
    return a
}

def py_npg_integers_m(st: [Int], low, high, rows, cols, closed) {
    if rows * cols == 0 {
        return zeros(py_size(rows), py_size(cols))
    }
    r = py_npg_irange(low, high, closed)
    A = zeros(py_size(rows), py_size(cols))
    for i to rows {
        for j to cols {
            A[i, j] = low + npr_gn_bounded(st, r)
        }
    }
    return A
}

#| Generator.shuffle(x) of a vector (or a Python list), and of a matrix's rows, in place; and
#| Generator.permutation of an int, a vector and a matrix.
def py_npg_shuffle(st: [Int], a: Arr) {
    if len(a) > 1 {
        npr_gn_shuffle(st, a)
    }
    return 0
}

def py_npg_shuffle_rows(st: [Int], A: Arr) {
    if numel(A) > 0 and shape(A)[0] > 1 {
        npr_gn_shuffle_rows(st, A)
    }
    return 0
}

def py_npg_perm_n(st: [Int], n) {
    a = zeros(max(n, 0))
    for i to len(a) {
        a[i] = i
    }
    py_npg_shuffle(st, a)
    return a
}

def py_npg_perm_v(st: [Int], x: Arr) {
    a = x * 1.0
    py_npg_shuffle(st, a)
    return a
}

def py_npg_perm_m(st: [Int], X: Arr) {
    rows = shape(X)[0]
    cols = shape(X)[1]
    idx = py_npg_perm_n(st, rows)
    A = zeros(rows, cols)
    for i to rows {
        for j to cols {
            A[i, j] = X[idx[i], j]
        }
    }
    return A
}

