# @@ imports
# @@ a generator from a seed
SEED = 42
rng = py_npg_new(SEED)
# @@ uniform draws in [0, 1)
FIRST = 4
u = py_npg_random_v(rng, FIRST)
print("first draws", join(" ", [fmt(py_x3, ".6f") for py_x3 in u]))
# @@ estimate pi from random points in the unit square
N = 20000
x = py_npg_random_v(rng, N)
y = py_npg_random_v(rng, N)
inside = len(py_nzflat(py_badd(x * x, y * y) < 1.0))
print("pi ~", fmt(py_div_i(py_int(4 * inside), N), ".4f"), "from", fmt(N + 0.0, "d"), "points")
# @@ dice
ROLLS = 12
rolls = py_npg_integers_v(rng, 1, 7, ROLLS, 0)
print("dice", fmt(rolls, "d"))
# @@ shuffle a deck
CARDS = 10
deck = py_arange(0, CARDS, 1)
py_npg_shuffle(rng, deck)
print("deck", fmt(deck, "d"))
# @@ normal draws
M = 1000
z = py_npg_normal_v(rng, 0.0, 1.0, M)
print("mean ", fmt(py_mean(z), ".4f"), ", std ", fmt(py_std(z), ".4f"), sep="")
# @@ checks
if not (inside == py_isum(py_badd(x * x, y * y) < 1.0)) {
    stop("AssertionError")
}
if not (min(rolls) >= 1 and max(rolls) <= 6) {
    stop("AssertionError")
}
